1: // Contract test for the 8-connected exterior pathfinder. FROZEN: do not modify.
2: #[path = "nav.rs"]
3: mod nav;
4: 
5: use nav::pathfind::astar_tile_grid_8;
6: use nav::{astar_grid_exterior, astar_grid_exterior_8, Floor, TileKind};
7: use std::collections::HashSet;
8: 
9: /// An exterior floor of open vacuum, with the given cells walled.
10: fn vacuum(w: u32, h: u32, walls: &[(u32, u32)]) -> Floor {
11:     let mut tiles = vec![TileKind::Empty; (w * h) as usize];
12:     for &(c, r) in walls {
13:         tiles[(r * w + c) as usize] = TileKind::Wall;
14:     }
15:     Floor::new(w, h, tiles)
16: }
17: 
18: // ---- the engine primitive ------------------------------------------------
19: 
20: /// A minimal TileSource so the engine function is testable on its own.
21: struct Open(u32, u32);
22: impl nav::pathfind::TileSource for Open {
23:     fn dims(&self) -> (u32, u32) { (self.0, self.1) }
24:     fn blocks(&self, c: i32, r: i32) -> bool {
25:         c < 0 || r < 0 || c >= self.0 as i32 || r >= self.1 as i32
26:     }
27: }
28: 
29: #[test]
30: fn engine_start_equals_goal_is_empty() {
31:     let s = Open(4, 4);
32:     assert_eq!(astar_tile_grid_8(&s, (1, 1), (1, 1), &HashSet::new()), Some(Vec::new()));
33: }
34: 
35: #[test]
36: fn engine_cuts_the_corner() {
37:     // (0,0) -> (3,3) is 3 diagonal steps, not 6 orthogonal ones.
38:     let s = Open(5, 5);
39:     let p = astar_tile_grid_8(&s, (0, 0), (3, 3), &HashSet::new()).expect("reachable");
40:     assert_eq!(p.len(), 3);
41:     assert_eq!(*p.last().unwrap(), (3, 3));
42: }
43: 
44: #[test]
45: fn engine_respects_extra_blocked() {
46:     let s = Open(4, 4);
47:     let extra: HashSet<(i32, i32)> = [(2, 3), (3, 2), (2, 2)].into_iter().collect();
48:     assert_eq!(astar_tile_grid_8(&s, (0, 0), (3, 3), &extra), None);
49: }
50: 
51: // ---- the game-side wrapper ----------------------------------------------
52: 
53: #[test]
54: fn game_wrapper_beats_the_4_connected_one_diagonally() {
55:     let f = vacuum(6, 6, &[]);
56:     let four = astar_grid_exterior(&f, (0, 0), (4, 4), &HashSet::new()).expect("reachable");
57:     let eight = astar_grid_exterior_8(&f, (0, 0), (4, 4), &HashSet::new()).expect("reachable");
58:     assert_eq!(four.len(), 8, "4-connected baseline");
59:     assert_eq!(eight.len(), 4, "8-connected cuts the corner");
60:     assert_eq!(*eight.last().unwrap(), (4, 4));
61: }
62: 
63: #[test]
64: fn game_wrapper_still_clamps_an_out_of_bounds_start() {
65:     // The ship is far outside the exterior grid; the search must clamp rather
66:     // than fail, exactly as the 4-connected wrapper does.
67:     let f = vacuum(5, 5, &[]);
68:     let p = astar_grid_exterior_8(&f, (-40, -40), (2, 2), &HashSet::new()).expect("clamped");
69:     assert_eq!(*p.last().unwrap(), (2, 2));
70: }
71: 
72: #[test]
73: fn game_wrapper_treats_walls_as_solid() {
74:     // A wall across column 2 with a gap at the bottom row.
75:     let walls: Vec<(u32, u32)> = (0..4).map(|r| (2u32, r)).collect();
76:     let f = vacuum(5, 5, &walls);
77:     let p = astar_grid_exterior_8(&f, (0, 0), (4, 0), &HashSet::new()).expect("gap at row 4");
78:     assert_eq!(*p.last().unwrap(), (4, 0));
79:     for &(c, r) in &p {
80:         assert_ne!(f.tile_at(c as i32, r as i32), TileKind::Wall, "walked into a wall");
81:     }
82: }
83: 
84: #[test]
85: fn game_wrapper_will_not_squeeze_between_two_wall_corners() {
86:     // Walls at (1,0) and (0,1) leave (0,0) and (1,1) touching only at a corner.
87:     // A unit has width; it must not slip diagonally through that seam.
88:     let f = vacuum(3, 3, &[(1, 0), (0, 1)]);
89:     assert_eq!(astar_grid_exterior_8(&f, (0, 0), (1, 1), &HashSet::new()), None);
90: }
91: 
92: #[test]
93: fn the_4_connected_wrapper_is_unchanged() {
94:     // Adding the new path must not alter the old one: still orthogonal-only.
95:     let f = vacuum(4, 4, &[]);
96:     let p = astar_grid_exterior(&f, (0, 0), (2, 2), &HashSet::new()).expect("reachable");
97:     assert_eq!(p.len(), 4, "4-connected must still cost 4 steps");
98: }

